class ChargingProfile(OCPPModel):
    """Charging_ Profile urn:x-oca:ocpp:uid:2:233255 A ChargingProfile consists of
    ChargingSchedule, describing the amount of power or current that can be delivered per
    time interval.

    Attributes:
        custom_data: Optional. A ``CustomData``.
        id: Identified_ Object. MRID. Numeric_ Identifier urn:x-enexis:ecdm:uid:1:569198 Id
            of ChargingProfile. Required.
        stack_level: Charging_ Profile. Stack_ Level. Counter urn:x-oca:ocpp:uid:1:569230
            Value determining level in hierarchy stack of profiles. Higher values have
            precedence over lower values. Lowest level is 0. Required.
        charging_profile_purpose: Required. A ``ChargingProfilePurpose``.
        charging_profile_kind: Required. A ``ChargingProfileKind``.
        recurrency_kind: Optional. A ``RecurrencyKind``.
        valid_from: Charging_ Profile. Valid_ From. Date_ Time urn:x-oca:ocpp:uid:1:569234
            Point in time at which the profile starts to be valid. If absent, the profile is
            valid as soon as it is received by the Charging Station. Optional. A timestamp.
        valid_to: Charging_ Profile. Valid_ To. Date_ Time urn:x-oca:ocpp:uid:1:569235 Point
            in time at which the profile stops to be valid. If absent, the profile is valid
            until it is replaced by another profile. Optional. A timestamp.
        charging_schedule: Required. A list of ChargingSchedule. At least 1 item. At most 3
            items.
        transaction_id: SHALL only be included if ChargingProfilePurpose is set to
            TxProfile. The transactionId is used to match the profile to a specific
            transaction. Optional. At most 36 characters.

    Example:
        >>> value = ChargingProfile.model_validate({
        ...     "id": 1,
        ...     "stackLevel": 1,
        ...     "chargingProfilePurpose": "ChargingStationExternalConstraints",
        ...     "chargingProfileKind": "Absolute",
        ...     "chargingSchedule": [
        ...         {
        ...             "id": 1,
        ...             "chargingRateUnit": "W",
        ...             "chargingSchedulePeriod": [
        ...                 {"startPeriod": 1, "limit": 1.5},
        ...             ],
        ...         },
        ...     ],
        ... })
        >>> type(value).__name__
        'ChargingProfile'
    """

    custom_data: CustomData | None = Field(default=None)
    id: StrictInt
    stack_level: StrictInt
    charging_profile_purpose: ChargingProfilePurpose
    charging_profile_kind: ChargingProfileKind
    recurrency_kind: RecurrencyKind | None = Field(default=None)
    valid_from: DateTime | None = Field(default=None)
    valid_to: DateTime | None = Field(default=None)
    charging_schedule: list[ChargingSchedule] = Field(min_length=1, max_length=3)
    transaction_id: StrictStr | None = Field(default=None, max_length=36)

    @model_validator(mode="after")
    def _check_rules(self) -> Self:
        if (
            self.transaction_id
            and self.charging_profile_purpose != ChargingProfilePurpose.TX_PROFILE
        ):
            raise rule_error(
                "transactionId", "only allowed when chargingProfilePurpose is TxProfile"
            )
        return self


