class EventData(OCPPModel):
    """Class to report an event notification for a component-variable.

    Attributes:
        custom_data: Optional. A ``CustomData``.
        event_id: Identifies the event. This field can be referred to as a cause by other
            events. Required.
        timestamp: Timestamp of the moment the report was generated. Required. A timestamp.
        trigger: Required. A ``EventTrigger``.
        cause: Refers to the Id of an event that is considered to be the cause for this
            event. Optional.
        actual_value: Actual value (_attributeType_ Actual) of the variable. The
            Configuration Variable &lt;&lt;configkey-reporting-value-
            size,ReportingValueSize&gt;&gt; can be used to limit
            GetVariableResult.attributeValue, VariableAttribute.value and
            EventData.actualValue. The max size of these values will always remain equal.
            Required. At most 2500 characters.
        tech_code: Technical (error) code as reported by component. Optional. At most 50
            characters.
        tech_info: Technical detail information as reported by component. Optional. At most
            500 characters.
        cleared: _Cleared_ is set to true to report the clearing of a monitored situation,
            i.e. a 'return to normal'. Optional.
        transaction_id: If an event notification is linked to a specific transaction, this
            field can be used to specify its transactionId. Optional. At most 36 characters.
        component: Required. A ``Component``.
        variable_monitoring_id: Identifies the VariableMonitoring which triggered the event.
            Optional.
        event_notification_type: Required. A ``EventNotification``.
        variable: Required. A ``Variable``.

    Example:
        >>> value = EventData.model_validate({
        ...     "eventId": 1,
        ...     "timestamp": "2025-01-02T03:04:05Z",
        ...     "trigger": "Alerting",
        ...     "actualValue": "x",
        ...     "component": {"name": "x"},
        ...     "eventNotificationType": "HardWiredNotification",
        ...     "variable": {"name": "x"},
        ... })
        >>> type(value).__name__
        'EventData'
    """

    custom_data: CustomData | None = Field(default=None)
    event_id: StrictInt
    timestamp: DateTime
    trigger: EventTrigger
    cause: StrictInt | None = Field(default=None)
    actual_value: StrictStr = Field(min_length=1, max_length=2500)
    tech_code: StrictStr | None = Field(default=None, max_length=50)
    tech_info: StrictStr | None = Field(default=None, max_length=500)
    cleared: StrictBool | None = Field(default=None)
    transaction_id: StrictStr | None = Field(default=None, max_length=36)
    component: Component
    variable_monitoring_id: StrictInt | None = Field(default=None)
    event_notification_type: EventNotification
    variable: Variable


class VariableMonitoring(OCPPModel):
    """A monitoring setting for a variable.

    Attributes:
        custom_data: Optional. A ``CustomData``.
        id: Identifies the monitor. Required.
        transaction: Monitor only active when a transaction is ongoing on a component
            relevant to this transaction. Required.
        value: Value for threshold or delta monitoring. For Periodic or PeriodicClockAligned
            this is the interval in seconds. Required.
        type: Required. A ``Monitor``.
        severity: The severity that will be assigned to an event that is triggered by this
            monitor. The severity range is 0-9, with 0 as the highest and 9 as the lowest
            severity level. The severity levels have the following meaning: + *0-Danger* +
            Indicates lives are potentially in danger. Urgent attention is needed and action
            should be taken immediately. + *1-Hardware Failure* + Indicates that the
            Charging Station is unable to continue regular operations due to Hardware
            issues. Action is required. + *2-System Failure* + Indicates that the Charging
            Station is unable to continue regular operations due to software or minor
            hardware issues. Action is required. + *3-Critical* + Indicates a critical
            error. Action is required. + *4-Error* + Indicates a non-urgent error. Action is
            required. + *5-Alert* + Indicates an alert event. Default severity for any type
            of monitoring event. + *6-Warning* + Indicates a warning event. Action may be
            required. + *7-Notice* + Indicates an unusual event. No immediate action is
            required. + *8-Informational* + Indicates a regular operational event. May be
            used for reporting, measuring throughput, etc. No action is required. +
            *9-Debug* + Indicates information useful to developers for debugging, not useful
            during operations. Required.

    Example:
        >>> value = VariableMonitoring.model_validate({
        ...     "id": 1,
        ...     "transaction": False,
        ...     "value": 1.5,
        ...     "type": "UpperThreshold",
        ...     "severity": 1,
        ... })
        >>> type(value).__name__
        'VariableMonitoring'
    """

    custom_data: CustomData | None = Field(default=None)
    id: StrictInt
    transaction: StrictBool
    value: Number
    type: Monitor
    severity: StrictInt


